<template>
  <div class="h5s_container" >
    <CubePlayer @error="onError" :h5sControl="control" :device-id="cameraItem?.deviceId || cameraItem?.id"  v-if="(cameraItem?.deviceId || cameraItem?.id) "></CubePlayer>
    <a-image
      v-else
      src=""
      fallback="data:image/png;base64,"
    />
  </div>
</template>
<script lang="ts">
import {
defineComponent, 
  reactive,
  toRefs,
} from "vue";
import { CubePlayer } from '@ghcloud/cube-player'
import {
  FullscreenOutlined,
  FullscreenExitOutlined,
  ZoomOutOutlined,
  ZoomInOutlined,
  RightOutlined,
  LeftOutlined,
  UpOutlined,
  DownOutlined
} from "@ant-design/icons-vue";

export default defineComponent({
  components: {
    CubePlayer,
    FullscreenOutlined,
    FullscreenExitOutlined,
    ZoomOutOutlined,
    ZoomInOutlined,
    RightOutlined,
    LeftOutlined,
    UpOutlined,
    DownOutlined
  },
  props: {
    idStr: {
      type: String,
      default: "cameraBox",
    },
    control: {
      type: Boolean,
      default: false,
    },
    tokenInfo:{
      type:Object,
      default:{}
    },
    cameraItem: {
      type: Object,
      default: () => {
        return {};
      },
    },
    snUrl:{
      type: String,
      default: "",
    }
  },
  setup(props, { emit }) {
    const state = reactive({
      player: null,
      tabShow: false
    });
    const onError = (msg,type)=>{
      if (type === 'PLAY_ERROR') {
        emit('error',props.cameraItem?.deviceId || props.cameraItem?.id)
      }
    }
    return {
      ...toRefs(state),
      onError
    }
  },
});
</script>
<style lang="less" scoped>
.h5s_container {
  width: 100%;
  height: 100%;
  position: relative;
  overflow: hidden;

  video {
    width: 100%;
    height: 100%;
    cursor: pointer;
    object-fit: inherit;
  }

  .bottomBtn {
    width: 100%;
    height: 40px;
    line-height: 40px;
    position: absolute;
    z-index: 10;
    background-color: rgba(255, 255, 255, 0.7);
    padding: 0 8px;
    transition: all 0.5s ease;
    cursor: pointer;
    

    &.showFooter {
      bottom: 0;
    }

    &.hideFooter {
      bottom: -40px;
    }

    .hideFooter {}

    .videoPlay {
      width: 15%;
    }

    .videoControl {
      width: 60%;
      text-align: center;
    }

    .videoOperate {
      border: 1px solid transparent;
      height: calc(100% - 2px);
    }
  }
}
:deep(.h5s_container_control){
  // width: 100% !important;
 svg{
  width: 15px !important;
  height: 15px !important;
 }
}
:deep(.cube-player){
  div[class^=_error-tex]{
    background-color: #fff;
    img{
      width: 0.3rem;
    }
    font-size: 0.072rem;
  }
}
</style>
